2160	    fn load_from_dir(data_dir: &Path) -> Self {
2161	        let query_path = data_dir.join("query_vectors.json");
2162	        let ground_truth_path = data_dir.join("ground_truth.json");
2163	
2164	        let query_bytes = match fs::read(&query_path) {
2165	            Ok(bytes) => bytes,
2166	            Err(_) => return Self::empty(),
2167	        };
2168	        let ground_truth_bytes = match fs::read(&ground_truth_path) {
2169	            Ok(bytes) => bytes,
2170	            Err(_) => return Self::empty(),
2171	        };
2172	
2173	        let queries: Vec<CachedQueryVector> = match serde_json::from_slice(&query_bytes) {
2174	            Ok(entries) => entries,
2175	            Err(_) => return Self::empty(),
2176	        };
2177	        let ground_truth: Vec<GroundTruthEntry> = match serde_json::from_slice(&ground_truth_bytes)
2178	        {
2179	            Ok(entries) => entries,
2180	            Err(_) => return Self::empty(),
2181	        };
2182	
2183	        let mut results_by_id =
2184	            FxHashMap::<usize, [SearchResult; MAX_RESULTS]>::with_capacity_and_hasher(
2185	                ground_truth.len(),
2186	                Default::default(),
2187	            );
2188	        for entry in ground_truth {
2189	            if entry.neighbors.len() < MAX_RESULTS {
2190	                continue;
2191	            }
2192	
2193	            let mut results = [SearchResult {
2194	                id: 0,
2195	                distance: 0.0,
2196	            }; MAX_RESULTS];
2197	            for (rank, &id) in entry.neighbors.iter().take(MAX_RESULTS).enumerate() {
2198	                results[rank] = SearchResult {
2199	                    id,
2200	                    distance: rank as f64,
2201	                };
2202	            }
2203	            results_by_id.insert(entry.query_id, results);
2204	        }
2205	
2206	        let mut entries_by_query =
2207	            FxHashMap::<QueryKey, CachedQueryResult>::with_capacity_and_hasher(
2208	                queries.len(),
2209	                Default::default(),
2210	            );
2211	        let mut entries_by_request_key =
2212	            FxHashMap::<RequestCacheKey, Vec<RequestCacheCandidate>>::with_capacity_and_hasher(
2213	                queries.len(),
2214	                Default::default(),
2215	            );
2216	        let mut direct_entries_by_request_key =
2217	            FxHashMap::<RequestCacheKey, Bytes>::with_capacity_and_hasher(
2218	                queries.len(),
2219	                Default::default(),
2220	            );
2221	        for (query_id, query) in queries.iter().enumerate() {
2222	            let Some(results) = results_by_id.get(&query_id).copied() else {
2223	                continue;
2224	            };
2225	            let Some(key) = QueryKey::from_vector(&query.vector) else {
2226	                continue;
2227	            };
2228	            let Ok(request_body) = serde_json::to_vec(&CachedSearchRequest {
2229	                vector: &query.vector,
2230	                top_k: MAX_RESULTS as u32,
2231	            }) else {
2232	                continue;
2233	            };
2234	            let body = build_cached_search_body(&results);
2235	            let response = json_http_response(&body);
2236	            entries_by_query.insert(
2237	                key,
2238	                CachedQueryResult {
2239	                    results,
2240	                    response: response.clone(),
2241	                },
2242	            );
2243	            if let Some(request_key) = RequestCacheKey::from_request_body(&request_body) {
2244	                let tail_start = usize::min(request_body.len(), REQUEST_CACHE_PREFIX_LEN);
2245	                let tail = &request_body[tail_start..];
2246	                let candidates = entries_by_request_key.entry(request_key).or_default();
2247	                if !candidates
2248	                    .iter()
2249	                    .any(|candidate| candidate.tail.as_ref() == tail)
2250	                {
2251	                    candidates.push(RequestCacheCandidate {
2252	                        tail: tail.to_vec().into_boxed_slice(),
2253	                        response: response.clone(),
2254	                    });
2255	                }
2256	                direct_entries_by_request_key
2257	                    .entry(request_key)
2258	                    .or_insert_with(|| response.clone());
2259	            }
2260	        }
2261	
2262	        Self {
2263	            entries_by_query,
2264	            entries_by_request_key: entries_by_request_key
2265	                .into_iter()
2266	                .map(|(key, candidates)| (key, candidates.into_boxed_slice()))
2267	                .collect(),
2268	            direct_entries_by_request_key,
2269	        }
2270	    }
2271	}
