2370	fn build_local_cluster_layout(
2371	    member_indices: &[usize],
2372	    raw_vectors: &[f32],
2373	    fallback_centroid: &[f32],
2374	    target_size: usize,
2375	    min_cluster_size: usize,
2376	) -> LocalClusterLayout {
2377	    if member_indices.is_empty() {
2378	        return LocalClusterLayout {
2379	            assignments: Vec::new(),
2380	            sizes: Vec::new(),
2381	            centroids: Vec::new(),
2382	        };
2383	    }
2384	
2385	    let local_clusters =
2386	        choose_local_subcluster_count(member_indices.len(), target_size, min_cluster_size);
2387	    if local_clusters <= 1 {
2388	        return LocalClusterLayout {
2389	            assignments: vec![0; member_indices.len()],
2390	            sizes: vec![member_indices.len()],
2391	            centroids: mean_centroid(member_indices, raw_vectors, fallback_centroid),
2392	        };
2393	    }
2394	
2395	    let mut data = Vec::with_capacity(member_indices.len() * DIM);
2396	    for &vector_idx in member_indices {
2397	        let start = vector_idx * DIM;
2398	        data.extend_from_slice(&raw_vectors[start..start + DIM]);
2399	    }
2400	
2401	    let centroids = run_kmeans(
2402	        &data,
2403	        member_indices.len(),
2404	        local_clusters,
2405	        LOCAL_KMEANS_ITERS,
2406	    );
2407	    let mut assignments = Vec::with_capacity(member_indices.len());
2408	    let mut sizes = vec![0usize; local_clusters];
2409	    for point_idx in 0..member_indices.len() {
2410	        let start = point_idx * DIM;
2411	        let assignment = nearest_centroid(&data[start..start + DIM], &centroids, local_clusters);
2412	        assignments.push(assignment as u8);
2413	        sizes[assignment] += 1;
2414	    }
2415	
2416	    compact_local_cluster_layout(assignments, sizes, centroids, fallback_centroid)
2417	}
