2419	#[inline(always)]
2420	fn choose_local_subcluster_count(
2421	    cluster_size: usize,
2422	    target_size: usize,
2423	    min_cluster_size: usize,
2424	) -> usize {
2425	    if cluster_size == 0 || target_size == 0 {
2426	        return 0;
2427	    }
2428	    if cluster_size < min_cluster_size {
2429	        return 0;
2430	    }
2431	
2432	    usize::min(
2433	        MAX_LOCAL_SUBCLUSTERS,
2434	        usize::max(1, cluster_size.div_ceil(target_size)),
2435	    )
2436	    .min(cluster_size)
2437	}
