2439	fn compact_local_cluster_layout(
2440	    mut assignments: Vec<u8>,
2441	    sizes: Vec<usize>,
2442	    centroids: Vec<f32>,
2443	    fallback_centroid: &[f32],
2444	) -> LocalClusterLayout {
2445	    let mut remap = vec![usize::MAX; sizes.len()];
2446	    let mut compact_sizes = Vec::with_capacity(sizes.len());
2447	    let mut compact_centroids = Vec::with_capacity(centroids.len());
2448	
2449	    for (old_idx, &size) in sizes.iter().enumerate() {
2450	        if size == 0 {
2451	            continue;
2452	        }
2453	        remap[old_idx] = compact_sizes.len();
2454	        compact_sizes.push(size);
2455	        let start = old_idx * DIM;
2456	        compact_centroids.extend_from_slice(&centroids[start..start + DIM]);
2457	    }
2458	
2459	    if compact_sizes.is_empty() {
2460	        return LocalClusterLayout {
2461	            assignments: vec![0; assignments.len()],
2462	            sizes: vec![assignments.len()],
2463	            centroids: fallback_centroid.to_vec(),
