2498	fn append_cluster_scan_ranges(
2499	    query: &QuantizedQuery,
2500	    cluster_id: usize,
2501	    index: &HierarchicalIndex,
2502	    local_subcluster_probe: usize,
2503	    scan_ranges: &mut Vec<ScanRange>,
2504	    deferred_scan_ranges: Option<&mut Vec<DeferredScanRange>>,
2505	) -> usize {
2506	    let cluster_start = index.cluster_offsets[cluster_id];
2507	    let cluster_end = index.cluster_offsets[cluster_id + 1];
2508	    if cluster_start == cluster_end {
2509	        return 0;
2510	    }
2511	
2512	    let local_start = index.local_cluster_offsets[cluster_id];
2513	    let local_end = index.local_cluster_offsets[cluster_id + 1];
2514	    let local_count = local_end - local_start;
2515	    if local_count == 0 {
2516	        return 0;
2517	    }
2518	    let centroid_start = local_start * DIM;
2519	    let centroid_end = local_end * DIM;
2520	    let mut local_distances = [0u32; MAX_LOCAL_SUBCLUSTERS];
2521	    distance::l2_distance_batch_u8(
2522	        &query.values,
2523	        &index.local_centroids_u8[centroid_start..centroid_end],
2524	        local_count,
2525	        &mut local_distances[..local_count],
2526	    );
2527	
2528	    let probe = usize::min(local_subcluster_probe, local_count);
2529	    if probe >= local_count {
2530	        let mut added = 0usize;
2531	        for local_idx in 0..local_count {
2532	            let global_local = local_start + local_idx;
2533	            let start = index.local_subcluster_offsets[global_local];
2534	            let end = index.local_subcluster_offsets[global_local + 1];
2535	            if start != end {
2536	                scan_ranges.push(ScanRange {
2537	                    start,
2538	                    end,
2539	                    centroid_distance_sq: local_distances[local_idx],
2540	                    cluster_id,
2541	                });
2542	                added += 1;
2543	            }
2544	        }
2545	        return added;
2546	    }
2547	
2548	    let mut best_local_ids = Vec::with_capacity(probe);
2549	    let mut best_local_distances = Vec::with_capacity(probe);
2550	    for (local_idx, &distance) in local_distances[..local_count].iter().enumerate() {
2551	        push_smallest_u32(
2552	            &mut best_local_ids,
2553	            &mut best_local_distances,
2554	            probe,
2555	            local_idx,
2556	            distance,
2557	        );
2558	    }
2559	    sort_pairs_u32(&mut best_local_ids, &mut best_local_distances);
2560	
2561	    let mut added = 0usize;
2562	    let mut is_seed = [false; MAX_LOCAL_SUBCLUSTERS];
2563	    for &local_idx in best_local_ids.iter() {
2564	        is_seed[local_idx] = true;
2565	    }
2566	    for local_idx in best_local_ids {
2567	        let global_local = local_start + local_idx;
2568	        let start = index.local_subcluster_offsets[global_local];
2569	        let end = index.local_subcluster_offsets[global_local + 1];
2570	        if start != end {
2571	            scan_ranges.push(ScanRange {
2572	                start,
2573	                end,
2574	                centroid_distance_sq: local_distances[local_idx],
2575	                cluster_id,
2576	            });
2577	            added += 1;
2578	        }
2579	    }
2580	    if let Some(deferred_scan_ranges) = deferred_scan_ranges {
2581	        for (local_idx, &distance) in local_distances[..local_count].iter().enumerate() {
2582	            if is_seed[local_idx] {
2583	                continue;
2584	            }
2585	            let global_local = local_start + local_idx;
2586	            let start = index.local_subcluster_offsets[global_local];
2587	            let end = index.local_subcluster_offsets[global_local + 1];
2588	            if start == end {
2589	                continue;
2590	            }
2591	            deferred_scan_ranges.push(DeferredScanRange {
2592	                start,
2593	                end,
2594	                centroid_distance_sq: distance,
2595	                lower_bound: cluster_lower_bound(
2596	                    distance,
2597	                    index.local_subcluster_quantized_radii[global_local],
2598	                ),
2599	                cluster_id,
2600	            });
2601	        }
2602	    }
2603	    added
2604	}
