2656	fn merge_scan_ranges(scan_ranges: &mut Vec<ScanRange>) {
2657	    if scan_ranges.len() <= 1 {
2658	        return;
2659	    }
2660	
2661	    let mut merged = Vec::with_capacity(scan_ranges.len());
2662	    let mut current = scan_ranges[0];
2663	    for range in &scan_ranges[1..] {
2664	        if range.start <= current.end {
2665	            current.end = current.end.max(range.end);
2666	            continue;
2667	        }
2668	        merged.push(current);
2669	        current = *range;
2670	    }
2671	    merged.push(current);
2672	    *scan_ranges = merged;
2673	}
