 338	    pub fn bulk_insert(&self, vectors: Vec<(u64, Vec<f32>)>) -> usize {
 339	        let mut inserted = 0usize;
 340	        let evicted_raw = {
 341	            let mut raw = self.raw.write();
 342	
 343	            raw.ids.reserve(vectors.len());
 344	            raw.vectors.reserve(vectors.len() * DIM);
 345	
 346	            for (id, vector) in vectors {
 347	                if vector.len() != DIM {
 348	                    continue;
 349	                }
 350	                raw.ids.push(id);
 351	                raw.vectors.extend_from_slice(&vector);
 352	                inserted += 1;
 353	            }
 354	
 355	            if inserted > 0 {
 356	                self.sync_official_cache_state(&mut raw)
 357	            } else {
 358	                false
 359	            }
 360	        };
 361	
 362	        if inserted > 0 {
 363	            if evicted_raw {
 364	                self.install_empty_index();
 365	            } else {
 366	                self.dirty.store(true, Ordering::Release);
 367	            }
 368	        }
 369	
 370	        inserted
 371	    }
