 10	#[inline(always)]
 11	pub fn l2_squared(a: &[f32], b: &[f32]) -> f32 {
 12	    debug_assert_eq!(a.len(), DIM);
 13	    debug_assert_eq!(b.len(), DIM);
 14	
 15	    #[cfg(target_arch = "x86_64")]
 16	    {
 17	        if is_x86_feature_detected!("avx512f") {
 18	            return unsafe { l2_squared_avx512(a, b) };
 19	        }
 20	        if is_x86_feature_detected!("avx2") {
 21	            return unsafe { l2_squared_avx2(a, b) };
 22	        }
 23	    }
 24	
 25	    l2_squared_scalar(a, b)
 26	}
