 49	pub fn l2_distance_batch(
 50	    query: &[f32],
 51	    vectors_flat: &[f32],
 52	    n_vectors: usize,
 53	    distances: &mut [f32],
 54	) {
 55	    debug_assert_eq!(query.len(), DIM);
 56	    debug_assert!(vectors_flat.len() >= n_vectors * DIM);
 57	    debug_assert!(distances.len() >= n_vectors);
 58	
 59	    #[cfg(target_arch = "x86_64")]
 60	    {
 61	        if is_x86_feature_detected!("avx512f") {
 62	            unsafe { l2_distance_batch_avx512(query, vectors_flat, n_vectors, distances) };
 63	            return;
 64	        }
 65	        if is_x86_feature_detected!("avx2") {
 66	            unsafe { l2_distance_batch_avx2(query, vectors_flat, n_vectors, distances) };
 67	            return;
 68	        }
 69	    }
 70	
 71	    for idx in 0..n_vectors {
 72	        let start = idx * DIM;
 73	        distances[idx] = l2_squared_scalar(query, &vectors_flat[start..start + DIM]);
 74	    }
 75	}
