262	#[target_feature(enable = "avx512f")]
263	unsafe fn l2_squared_avx512(a: &[f32], b: &[f32]) -> f32 {
264	    use std::arch::x86_64::*;
265	
266	    let a_ptr = a.as_ptr();
267	    let b_ptr = b.as_ptr();
268	
269	    let d0 = _mm512_sub_ps(_mm512_loadu_ps(a_ptr), _mm512_loadu_ps(b_ptr));
270	    let mut sum = _mm512_mul_ps(d0, d0);
271	
272	    let d1 = _mm512_sub_ps(
273	        _mm512_loadu_ps(a_ptr.add(16)),
274	        _mm512_loadu_ps(b_ptr.add(16)),
275	    );
276	    sum = _mm512_fmadd_ps(d1, d1, sum);
277	
278	    let d2 = _mm512_sub_ps(
279	        _mm512_loadu_ps(a_ptr.add(32)),
280	        _mm512_loadu_ps(b_ptr.add(32)),
281	    );
282	    sum = _mm512_fmadd_ps(d2, d2, sum);
283	
284	    let d3 = _mm512_sub_ps(
285	        _mm512_loadu_ps(a_ptr.add(48)),
286	        _mm512_loadu_ps(b_ptr.add(48)),
287	    );
288	    sum = _mm512_fmadd_ps(d3, d3, sum);
289	
290	    let d4 = _mm512_sub_ps(
291	        _mm512_loadu_ps(a_ptr.add(64)),
292	        _mm512_loadu_ps(b_ptr.add(64)),
293	    );
294	    sum = _mm512_fmadd_ps(d4, d4, sum);
295	
296	    let d5 = _mm512_sub_ps(
297	        _mm512_loadu_ps(a_ptr.add(80)),
298	        _mm512_loadu_ps(b_ptr.add(80)),
299	    );
300	    sum = _mm512_fmadd_ps(d5, d5, sum);
301	
302	    let d6 = _mm512_sub_ps(
303	        _mm512_loadu_ps(a_ptr.add(96)),
304	        _mm512_loadu_ps(b_ptr.add(96)),
305	    );
306	    sum = _mm512_fmadd_ps(d6, d6, sum);
307	
308	    let d7 = _mm512_sub_ps(
309	        _mm512_loadu_ps(a_ptr.add(112)),
310	        _mm512_loadu_ps(b_ptr.add(112)),
311	    );
312	    sum = _mm512_fmadd_ps(d7, d7, sum);
313	
314	    _mm512_reduce_add_ps(sum)
315	}
