372	unsafe fn l2_squared_avx2(a: &[f32], b: &[f32]) -> f32 {
373	    use std::arch::x86_64::*;
374	
375	    let a_ptr = a.as_ptr();
376	    let b_ptr = b.as_ptr();
377	
378	    let mut sum0 = _mm256_setzero_ps();
379	    let mut sum1 = _mm256_setzero_ps();
380	    let mut sum2 = _mm256_setzero_ps();
381	    let mut sum3 = _mm256_setzero_ps();
382	
383	    for offset in (0..DIM).step_by(32) {
384	        let d0 = _mm256_sub_ps(
385	            _mm256_loadu_ps(a_ptr.add(offset)),
386	            _mm256_loadu_ps(b_ptr.add(offset)),
387	        );
388	        let d1 = _mm256_sub_ps(
389	            _mm256_loadu_ps(a_ptr.add(offset + 8)),
390	            _mm256_loadu_ps(b_ptr.add(offset + 8)),
391	        );
392	        let d2 = _mm256_sub_ps(
393	            _mm256_loadu_ps(a_ptr.add(offset + 16)),
394	            _mm256_loadu_ps(b_ptr.add(offset + 16)),
395	        );
396	        let d3 = _mm256_sub_ps(
397	            _mm256_loadu_ps(a_ptr.add(offset + 24)),
398	            _mm256_loadu_ps(b_ptr.add(offset + 24)),
399	        );
400	        sum0 = _mm256_add_ps(sum0, _mm256_mul_ps(d0, d0));
401	        sum1 = _mm256_add_ps(sum1, _mm256_mul_ps(d1, d1));
402	        sum2 = _mm256_add_ps(sum2, _mm256_mul_ps(d2, d2));
403	        sum3 = _mm256_add_ps(sum3, _mm256_mul_ps(d3, d3));
404	    }
405	
406	    horizontal_sum_m256(_mm256_add_ps(
407	        _mm256_add_ps(sum0, sum1),
408	        _mm256_add_ps(sum2, sum3),
409	    ))
410	}
