516	    let hi = _mm256_extractf128_ps(sum, 1);
517	    let sum = _mm_add_ps(lo, hi);
518	    let sum = _mm_hadd_ps(sum, sum);
519	    let sum = _mm_hadd_ps(sum, sum);
520	    _mm_cvtss_f32(sum)
