642	#[target_feature(enable = "avx2")]
643	unsafe fn l2_squared_u8_avx2(query: &[u8; DIM], vector: &[u8]) -> u32 {
644	    use std::arch::x86_64::*;
645	
646	    let q_ptr = query.as_ptr();
647	    let v_ptr = vector.as_ptr();
648	    let mut sum = _mm256_setzero_si256();
649	
650	    for offset in (0..DIM).step_by(16) {
651	        let q = _mm_loadu_si128(q_ptr.add(offset) as *const __m128i);
652	        let v = _mm_loadu_si128(v_ptr.add(offset) as *const __m128i);
653	        let q16 = _mm256_cvtepu8_epi16(q);
654	        let v16 = _mm256_cvtepu8_epi16(v);
655	        let delta = _mm256_sub_epi16(q16, v16);
656	        let squared = _mm256_madd_epi16(delta, delta);
657	        sum = _mm256_add_epi32(sum, squared);
658	    }
659	
660	    let lo = _mm256_castsi256_si128(sum);
661	    let hi = _mm256_extracti128_si256(sum, 1);
662	    let sum = _mm_add_epi32(lo, hi);
663	    let sum = _mm_hadd_epi32(sum, sum);
664	    let sum = _mm_hadd_epi32(sum, sum);
665	    _mm_cvtsi128_si32(sum) as u32
666	}
