684	    let q5 = _mm256_cvtepu8_epi16(_mm_loadu_si128(q_ptr.add(80) as *const __m128i));
685	    let q6 = _mm256_cvtepu8_epi16(_mm_loadu_si128(q_ptr.add(96) as *const __m128i));
686	    let q7 = _mm256_cvtepu8_epi16(_mm_loadu_si128(q_ptr.add(112) as *const __m128i));
687	
688	    let v_ptr = vectors_flat.as_ptr();
689	    for idx in 0..n_vectors {
690	        let base = v_ptr.add(idx * DIM);
691	        let mut sum = _mm256_setzero_si256();
692	
693	        let v0 = _mm256_cvtepu8_epi16(_mm_loadu_si128(base as *const __m128i));
694	        let v1 = _mm256_cvtepu8_epi16(_mm_loadu_si128(base.add(16) as *const __m128i));
695	        let v2 = _mm256_cvtepu8_epi16(_mm_loadu_si128(base.add(32) as *const __m128i));
696	        let v3 = _mm256_cvtepu8_epi16(_mm_loadu_si128(base.add(48) as *const __m128i));
697	        let v4 = _mm256_cvtepu8_epi16(_mm_loadu_si128(base.add(64) as *const __m128i));
698	        let v5 = _mm256_cvtepu8_epi16(_mm_loadu_si128(base.add(80) as *const __m128i));
699	        let v6 = _mm256_cvtepu8_epi16(_mm_loadu_si128(base.add(96) as *const __m128i));
700	        let v7 = _mm256_cvtepu8_epi16(_mm_loadu_si128(base.add(112) as *const __m128i));
701	
702	        let d0 = _mm256_sub_epi16(q0, v0);
703	        let d1 = _mm256_sub_epi16(q1, v1);
704	        let d2 = _mm256_sub_epi16(q2, v2);
705	        let d3 = _mm256_sub_epi16(q3, v3);
706	        let d4 = _mm256_sub_epi16(q4, v4);
707	        let d5 = _mm256_sub_epi16(q5, v5);
708	        let d6 = _mm256_sub_epi16(q6, v6);
709	        let d7 = _mm256_sub_epi16(q7, v7);
710	
711	        sum = _mm256_add_epi32(sum, _mm256_madd_epi16(d0, d0));
712	        sum = _mm256_add_epi32(sum, _mm256_madd_epi16(d1, d1));
713	        sum = _mm256_add_epi32(sum, _mm256_madd_epi16(d2, d2));
714	        sum = _mm256_add_epi32(sum, _mm256_madd_epi16(d3, d3));
715	        sum = _mm256_add_epi32(sum, _mm256_madd_epi16(d4, d4));
716	        sum = _mm256_add_epi32(sum, _mm256_madd_epi16(d5, d5));
717	        sum = _mm256_add_epi32(sum, _mm256_madd_epi16(d6, d6));
718	        sum = _mm256_add_epi32(sum, _mm256_madd_epi16(d7, d7));
719	
720	        let lo = _mm256_castsi256_si128(sum);
721	        let hi = _mm256_extracti128_si256(sum, 1);
722	        let sum = _mm_add_epi32(lo, hi);
723	        let sum = _mm_hadd_epi32(sum, sum);
724	        let sum = _mm_hadd_epi32(sum, sum);
725	        distances[idx] = _mm_cvtsi128_si32(sum) as u32;
726	    }
727	}
