2990	
2991	        let mut sums = vec![0.0f64; clusters * dims];
2992	        let mut counts = vec![0usize; clusters];
2993	        for (point_idx, &cluster_id) in assignments.iter().enumerate() {
2994	            counts[cluster_id] += 1;
