3028	fn select_coarse_dimensions(sample: &[f32], coarse_dims: usize) -> Vec<u8> {
3029	    if coarse_dims == 0 || sample.is_empty() {
3030	        return Vec::new();
3031	    }
3032	
3033	    let points = sample.len() / DIM;
3034	    if points == 0 {
3035	        return Vec::new();
3036	    }
3037	
3038	    let mut means = [0.0f64; DIM];
3039	    for vector in sample.chunks_exact(DIM) {
3040	        for dim in 0..DIM {
3041	            means[dim] += vector[dim] as f64;
3042	        }
3043	    }
3044	    let inv_points = 1.0f64 / points as f64;
3045	    for mean in means.iter_mut() {
3046	        *mean *= inv_points;
3047	    }
3048	
3049	    let mut variances = [0.0f64; DIM];
3050	    for vector in sample.chunks_exact(DIM) {
3051	        for dim in 0..DIM {
3052	            let delta = vector[dim] as f64 - means[dim];
3053	            variances[dim] += delta * delta;
3054	        }
3055	    }
3056	
3057	    let mut ranked_dims = (0..DIM).collect::<Vec<_>>();
3058	    ranked_dims.sort_unstable_by(|&lhs, &rhs| {
3059	        variances[rhs]
3060	            .partial_cmp(&variances[lhs])
3061	            .unwrap_or(std::cmp::Ordering::Equal)
3062	    });
3063	
3064	    ranked_dims
3065	        .into_iter()
3066	        .take(coarse_dims.min(DIM))
3067	        .map(|dim| dim as u8)
3068	        .collect()
3069	}
