3116	            variances[rhs]
3117	                .partial_cmp(&variances[lhs])
3118	                .unwrap_or(std::cmp::Ordering::Equal)
3119	        });
3120	        for (offset, dim) in ranked_dims.into_iter().take(coarse_dims).enumerate() {
3121	            dst[offset] = dim as u8;
3122	        }
3123	    }
