3205	            }
3206	        }
3207	
3208	        for cluster_id in 0..clusters {
3209	            let count = counts[cluster_id];
3210	            if count == 0 {
3211	                continue;
3212	            }
3213	
3214	            let inv = 1.0f64 / count as f64;
3215	            let start = cluster_id * DIM;
3216	            for dim in 0..DIM {
3217	                centroids[start + dim] = (sums[start + dim] * inv) as f32;
3218	            }
3219	        }
3220	    }
3221	
3222	    centroids
3223	}
