3254	fn compute_quantization_params(vectors: &[f32]) -> (f32, f32) {
3255	    let mut min_value = f32::INFINITY;
3256	    let mut max_value = f32::NEG_INFINITY;
3257	
3258	    for &value in vectors.iter() {
3259	        min_value = min_value.min(value);
3260	        max_value = max_value.max(value);
3261	    }
3262	
3263	    if !min_value.is_finite() || !max_value.is_finite() || max_value <= min_value {
3264	        return (0.0, 0.0);
3265	    }
3266	
3267	    (min_value, 255.0 / (max_value - min_value))
3268	}
