3271	fn quantize_value(value: f32, quant_min: f32, quant_scale: f32) -> u8 {
3272	    if quant_scale <= 0.0 {
3273	        return 0;
3274	    }
3275	
3276	    ((value - quant_min) * quant_scale)
3277	        .round()
3278	        .clamp(0.0, 255.0) as u8
3279	}
