3410	#[inline(always)]
3411	fn push_candidate_batch(start_position: usize, distances: &[u32], candidates: &mut CandidateHeap) {
3412	    if distances.is_empty() || candidates.limit == 0 {
3413	        return;
3414	    }
3415	
3416	    let mut position = start_position;
3417	    let mut offset = 0usize;
3418	    if !candidates.is_full() {
3419	        let fill = usize::min(candidates.limit - candidates.len(), distances.len());
3420	        for &distance in &distances[..fill] {
3421	            candidates.push(position, distance);
3422	            position += 1;
3423	        }
3424	        offset = fill;
3425	        if offset == distances.len() {
3426	            return;
3427	        }
3428	    }
3429	
3430	    let mut cutoff = candidates.worst_distance();
3431	    for &distance in &distances[offset..] {
3432	        if distance < cutoff {
3433	            candidates.push(position, distance);
3434	            cutoff = candidates.worst_distance();
3435	        }
3436	        position += 1;
3437	    }
3438	}
