3605	fn scan_primary_quantized_subspace(
3606	    query: &QuantizedQuery,
3607	    index: &HierarchicalIndex,
3608	    scan_ranges: &[ScanRange],
3609	    coarse_dim_count: usize,
3610	    coarse_candidates_per_primary: usize,
3611	    candidates: &mut CandidateHeap,
3612	) -> (usize, usize, usize) {
3613	    if scan_ranges.is_empty() {
3614	        return (0, 0, 0);
3615	    }
3616	
3617	    let mut coarse_query_values = [0u8; DIM];
3618	    let mut coarse_candidates = CandidateHeap::new(coarse_candidates_per_primary);
3619	    let mut current_primary = usize::MAX;
3620	    let mut current_primary_len = 0usize;
3621	    let mut scanned = 0usize;
3622	    let mut rescored = 0usize;
3623	    let mut pruned = 0usize;
3624	
3625	    for range in scan_ranges {
3626	        if range.start == range.end {
3627	            continue;
3628	        }
3629	
3630	        let primary_id = range.cluster_id / index.secondary_clusters;
3631	        if primary_id != current_primary {
3632	            if current_primary != usize::MAX {
3633	                let rescored_now =
3634	                    rescore_coarse_candidates(query, index, &coarse_candidates, candidates);
3635	                rescored += rescored_now;
3636	                pruned += current_primary_len.saturating_sub(rescored_now);
3637	                coarse_candidates.clear();
3638	                current_primary_len = 0;
3639	            }
3640	            populate_selected_query_values(
3641	                &query.values,
3642	                &index.coarse_dim_indices,
3643	                coarse_dim_count,
3644	                primary_id,
3645	                &mut coarse_query_values,
3646	            );
3647	            current_primary = primary_id;
3648	        }
3649	
3650	        let range_len = range.end - range.start;
3651	        scanned += range_len;
3652	        current_primary_len += range_len;
3653	        scan_cluster_quantized_subspace(
3654	            &coarse_query_values[..coarse_dim_count],
3655	            &index.cluster_vectors_u8_coarse
3656	                [range.start * coarse_dim_count..range.end * coarse_dim_count],
3657	            coarse_dim_count,
3658	            range.start,
3659	            &mut coarse_candidates,
3660	        );
3661	    }
3662	
3663	    if current_primary != usize::MAX {
3664	        let rescored_now = rescore_coarse_candidates(query, index, &coarse_candidates, candidates);
3665	        rescored += rescored_now;
3666	        pruned += current_primary_len.saturating_sub(rescored_now);
3667	    }
3668	
3669	    (scanned, rescored, pruned)
3670	}
