3672	#[inline(always)]
3673	fn rescore_coarse_candidates(
3674	    query: &QuantizedQuery,
3675	    index: &HierarchicalIndex,
3676	    coarse_candidates: &CandidateHeap,
3677	    exact_candidates: &mut CandidateHeap,
3678	) -> usize {
3679	    let mut positions = coarse_candidates.positions().to_vec();
3680	    positions.sort_unstable();
3681	    let mut distances = [0u32; DISTANCE_BATCH_CHUNK];
3682	    let mut rescored = 0usize;
3683	    let mut cursor = 0usize;
3684	
3685	    while cursor < positions.len() {
3686	        let run_start = positions[cursor];
3687	        let mut run_len = 1usize;
3688	        while cursor + run_len < positions.len()
3689	            && positions[cursor + run_len] == positions[cursor + run_len - 1] + 1
3690	        {
3691	            run_len += 1;
3692	        }
3693	
3694	        let mut run_offset = 0usize;
3695	        while run_offset < run_len {
3696	            let batch = usize::min(DISTANCE_BATCH_CHUNK, run_len - run_offset);
3697	            let position = run_start + run_offset;
3698	            let start = position * DIM;
3699	            let end = start + batch * DIM;
3700	            distance::l2_distance_batch_u8(
3701	                &query.values,
3702	                &index.cluster_vectors_u8[start..end],
3703	                batch,
3704	                &mut distances[..batch],
3705	            );
3706	            push_candidate_batch(position, &distances[..batch], exact_candidates);
3707	            rescored += batch;
3708	            run_offset += batch;
3709	        }
3710	
3711	        cursor += run_len;
3712	    }
3713	
3714	    rescored
3715	}
