3717	#[inline(always)]
3718	fn scan_cluster_quantized_block_pruned(
3719	    query: &QuantizedQuery,
3720	    index: &HierarchicalIndex,
3721	    cluster_id: usize,
3722	    block_query_values: &[u8],
3723	    candidates: &mut CandidateHeap,
3724	) -> (usize, usize) {
3725	    let start = index.cluster_offsets[cluster_id];
3726	    let end = index.cluster_offsets[cluster_id + 1];
3727	    if start >= end {
3728	        return (0, 0);
3729	    }
3730	
3731	    let block_start = index.cluster_block_offsets[cluster_id];
3732	    let block_end = index.cluster_block_offsets[cluster_id + 1];
3733	    if block_start >= block_end {
3734	        scan_cluster_quantized(
3735	            query,
3736	            &index.cluster_vectors_u8[start * DIM..end * DIM],
3737	            start,
3738	            candidates,
3739	        );
3740	        return (end - start, 0);
3741	    }
3742	
3743	    let mut scanned = 0usize;
3744	    let mut pruned = 0usize;
3745	    for block_idx in block_start..block_end {
3746	        let position = start + (block_idx - block_start) * BLOCK_BOUND_SIZE;
3747	        let position_end = usize::min(position + BLOCK_BOUND_SIZE, end);
3748	        let block_len = position_end - position;
3749	        if block_len == 0 {
3750	            continue;
3751	        }
3752	
3753	        if candidates.is_full() {
3754	            let bounds_start = block_idx * index.block_bound_dims;
3755	            let bounds_end = bounds_start + index.block_bound_dims;
3756	            let lower_bound = block_box_lower_bound_u8(
3757	                block_query_values,
3758	                &index.cluster_block_mins[bounds_start..bounds_end],
3759	                &index.cluster_block_maxs[bounds_start..bounds_end],
3760	            );
3761	            if lower_bound >= candidates.worst_distance() {
3762	                pruned += block_len;
3763	                continue;
3764	            }
3765	        }
3766	
3767	        scan_cluster_quantized(
3768	            query,
3769	            &index.cluster_vectors_u8[position * DIM..position_end * DIM],
3770	            position,
3771	            candidates,
3772	        );
3773	        scanned += block_len;
3774	    }
3775	
3776	    (scanned, pruned)
3777	}
