3779	#[inline(always)]
3780	fn scan_cluster_quantized_radius_pruned(
3781	    query: &QuantizedQuery,
3782	    vectors: &[u8],
3783	    radii: &[u16],
3784	    start_position: usize,
3785	    centroid_distance_sq: u32,
